// Break a topic name into short axis-label lines, but only at natural
// points: after ：/与/space and before （. English words and acronyms
// (3NF, BCNF, WAL, ARIES, MVCC, ACID) are atomic units and never split.
const LABEL_BREAK_AFTER = new Set(['：', '与', ' ']);
const LABEL_MAX_WIDTH = 14; // display units: CJK char = 2, ASCII = 1

function labelUnits(text) {
  const units = [];
  let cur = '';
  for (const ch of text) {
    if (ch === '（' && cur) { units.push(cur); cur = '（'; continue; }
    cur += ch;
    if (LABEL_BREAK_AFTER.has(ch)) { units.push(cur); cur = ''; }
  }
  if (cur) units.push(cur);
  return units;
}

function displayWidth(s) {
  let w = 0;
  for (const ch of s) w += ch.codePointAt(0) > 0xFF ? 2 : 1;
  return w;
}

function wrapUnits(units, max) {
  const lines = [];
  let cur = '';
  for (const u of units) {
    if (cur && displayWidth(cur.trimEnd()) + displayWidth(u) > max) {
      lines.push(cur.trimEnd());
      cur = u;
    } else {
      cur += u;
    }
  }
  if (cur) lines.push(cur.trimEnd());
  return lines;
}

function axisLabel(item) {
  const lines = [];
  // ： ends a segment: "索引：" / "B+树与哈希索引", never "索引：B+" / "树…"
  for (const seg of item.topic_name.split(/(?<=：)/)) {
    lines.push(...wrapUnits(labelUnits(seg), LABEL_MAX_WIDTH));
  }
  return item.topic_id + '\n' + lines.join('\n');
}

