        // adjacent lines (small vertical gap + horizontal overlap) back
        // into one label
        const legend = raw.filter(t =>
          t.content === '覆盖度' || t.content === '考试权重');
        const lines = raw.filter(t => !legend.includes(t));
        const groups = [];
        for (const line of lines) {
          const g = groups.find(g2 => {
            const last = g2[g2.length - 1];
            const gap = line.rect.y - (last.rect.y + last.rect.h);
            const xOverlap = !(line.rect.x + line.rect.w < last.rect.x ||
                               last.rect.x + last.rect.w < line.rect.x);
            return gap >= -1 && gap <= 4 && xOverlap;
